import { createSlice } from '@reduxjs/toolkit';
import { Location } from '@src/domain/entities/location';
import { fetchLocationDetail } from './thunk';

interface LocationState {
  data: Location | null;
  status: 'idle' | 'loading' | 'succeeded' | 'failed';
  error: string | null;
}

const initialState: LocationState = {
  data: null,
  status: 'idle',
  error: null,
};

const locationSlice = createSlice({
  name: 'location',
  initialState,
  reducers: {
    resetLocation: (state) => {
      state.data = null;
      state.error = null;
      state.status = 'idle';
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchLocationDetail.pending, (state) => {
        state.status = 'loading';
        state.error = null;
      })
      .addCase(fetchLocationDetail.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.data = action.payload;
      })
      .addCase(fetchLocationDetail.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message ?? 'Failed to search location';
      });
  },
});

export default locationSlice;
