import { View, Text, FlatList, TouchableOpacity, Image } from 'react-native'
import React, { useEffect, useRef, useState } from 'react'
import { createStyles, RadioButton, useTheme, Theme } from '@core/ui';
import { registerStaticData } from '@src/domain/entities/cms/loan_register/registerStaticData';
import useCSS from "@src/presentation/style";
import DataSelectList from './type';
import getImg from '@src/utils/getImg';

type SelectListProps = {
    listSelect: DataSelectList[] | undefined;
    onSelected?: () => void;
}

export default function SelectList(Props: SelectListProps) {
    const { theme } = useTheme()
    const styles = useStyles();
    const css = useCSS();
    const renderOption = ({ item, index }: { item: DataSelectList, index: number }) => {
        return (
            <TouchableOpacity onPress={() => { handlePress(item) }}>
                <View style={[styles.row, index > 0 && { borderTopWidth: theme.Size.Vertical.XXSmall, borderTopColor: theme.Colors.Border.Neutral300 }]}>
                    <Text style={styles.label}>{item.title}</Text>
                    <Image style={[css.ml_base, { height: theme.Size.Vertical.Regular, width: theme.Size.Horizontal.Base, resizeMode: 'contain' }]} source={getImg('/assets/images/icons/right_arrow.png')} />
                </View>
                {item.divider && <View style={{ borderTopWidth: 1, borderColor: theme.Colors.Border.Neutral300 }} />}
            </TouchableOpacity>
        );
    };
    const handlePress = (item: DataSelectList) => {
        Props.onSelected?.();
        item?.fn?.()
    };
    return (
        <View>
            <FlatList
                data={Props.listSelect}
                pagingEnabled={true}
                horizontal={false}
                renderItem={renderOption}
                contentContainerStyle={styles.container}
                keyExtractor={(item) => 'key_' + item.id}
            />
        </View>
    )
}


const useStyles = createStyles((theme: Theme) => ({
    container: {
        paddingVertical: theme.Size.Vertical.Medium,
    },
    row: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'center',
        paddingVertical: theme.Size.vs(10),
    },
    label: {
        ...theme.Typography.TextBody.Regular,
    },
}));
