import { TYPES } from '@src/di/types/types';
import { inject } from 'inversify';
import type { IGenerateContractRepository } from '@src/domain/interfaces/loan_collateral/generate_contract';
import { GenerateContractPayload } from './generate_contract_query';

export class GenerateContractHandler {
    private readonly _generateContractRepository: IGenerateContractRepository;

    constructor(@inject(TYPES.IGenerateContractRepository) generateContractRepository: IGenerateContractRepository) {
        this._generateContractRepository = generateContractRepository;
    }

    handle(dataReq: GenerateContractPayload) {
        return this._generateContractRepository.generateContract(dataReq);
    }
}
