import { FormInput, Text, useTheme } from '@core/ui';
import React, { useEffect, useState } from 'react';
import useCSS from '@src/presentation/style';
import { TextInput, View } from 'react-native';
import { CURRENCY } from '@src/utils/constants';

interface Props {
    value: number;
    onValueChange: (value: number) => void;
    currency?: string;
    hasFocus?: boolean;
}

const CurrencyInput: React.FC<Props> = ({ value, onValueChange, currency = CURRENCY, hasFocus = false, ...props }) => {
    const css = useCSS();
    const { theme } = useTheme();

    const formatCurrency = (num: number) => {
        return num.toLocaleString('en-US');
    };
    const [displayValue, setDisplayValue] = useState(formatCurrency(value));
    const [isFocus, setIsFocus] = useState(hasFocus);
    const handleChange = (text: string) => {
        const numericValue = Number(text.replace(/\D/g, '')); // Lọc bỏ ký tự không phải số
        setDisplayValue(formatCurrency(numericValue));
        onValueChange(numericValue);
    };
    useEffect(() => {
        setIsFocus(hasFocus);
    }, [hasFocus]);
    useEffect(() => {
        setDisplayValue(formatCurrency(value));
    }, [value]);
    return (
        <View style={[css.border_b_1, isFocus ? css.border_b_orange_600 : css.border_b_neutral_300]}>
            <View style={[css.row, css.justify_center, css.items_end]}>
                <View style={[{ height: theme.Size.Vertical.ExtraLarge }, css.row, css.items_center]}>
                    <TextInput
                        keyboardType='number-pad'
                        autoFocus={isFocus}
                        value={displayValue}
                        onChangeText={handleChange}
                        onFocus={() => setIsFocus(true)}
                        onBlur={() => setIsFocus(false)}
                        placeholder={'0'}
                        placeholderTextColor={theme.Colors.Border.Neutral400}
                        selectionColor={theme.Colors.Main.Orange}
                        style={[css.text_center, css.font_semibold, { ...theme.Typography.LargeTitle.Semibold }]}
                        {...props}
                    />
                </View>
                <Text style={[css.ml_small, css.mb_medium, css.text_subheadline]}>{currency}</Text>
            </View>
        </View>
    );
};

export default React.memo(CurrencyInput);
